import{_ as d,C as r,o as c,c as l,j as s,a as o,E as t,a2 as n}from"./chunks/framework.BxGh02fV.js";const _=JSON.parse('{"title":"Code et stacks","description":"","frontmatter":{"title":"Code et stacks"},"headers":[],"relativePath":"agent/code.md","filePath":"agent/code.md"}'),i={name:"agent/code.md"};function u(f,a,m,p,k,h){const e=r("Ask");return c(),l("div",null,[a[0]||(a[0]=s("h1",{id:"code-et-stacks",tabindex:"-1"},[o("Code et stacks "),s("a",{class:"header-anchor",href:"#code-et-stacks","aria-label":'Permalink to "Code et stacks"'},"​")],-1)),a[1]||(a[1]=s("p",null,[o("Une stack (un module) est une partie de votre code : son dossier sous "),s("code",null,"codebase/"),o(", son modèle, ses langages. Vous venez à ce parcours pour déclarer un module, choisir un modèle, échafauder le code de départ, construire, lancer les tests, faire le ménage ou ramener le travail d'un worktree dans le dépôt.")],-1)),a[2]||(a[2]=s("h2",{id:"ce-que-vous-demandez-a-l-agent",tabindex:"-1"},[o("Ce que vous demandez à l'agent "),s("a",{class:"header-anchor",href:"#ce-que-vous-demandez-a-l-agent","aria-label":`Permalink to "Ce que vous demandez à l'agent"`},"​")],-1)),t(e,{say:"Quels modèles de stack existent, et que contient le modèle rust ?",verb:"effortless_stack_model_list",family:"stacks"}),t(e,{say:"Ajoute un module api avec le modèle node.",verb:"effortless_stack_add",family:"stacks",args:'{"id":"api","scaffold_template":"node"}'}),t(e,{say:"Quelles sont les stacks déclarées dans ce projet ?",verb:"effortless_stack_list",family:"stacks"}),t(e,{say:"Le module api est en Rust et en TypeScript : déclare-le.",verb:"effortless_stack_declare_languages",family:"stacks",args:'{"stack_id":"api","languages":[{"id":"rust"},{"id":"typescript"}]}'}),t(e,{say:"Quelle commande lance les tests du module api ? Et le lint ?",verb:"effortless_stack_cycle",family:"stacks",args:'{"stack_id":"api","kind":"test"}'}),t(e,{say:"Construis le module desktop.",verb:"effortless_stack_build",family:"stacks",args:'{"stack_id":"desktop"}'}),t(e,{say:"Montre-moi ce que le ménage ferait sur desktop, sans rien supprimer.",verb:"effortless_stack_housekeeping",family:"stacks",args:'{"stack_id":"desktop","apply":false}'}),t(e,{say:"Déplace le code qui traîne à la racine sous codebase/.",verb:"effortless_codebase_relocate",family:"installation",args:'{"dry_run":false}'}),t(e,{say:"Ramène le travail du worktree ../wt-api dans le dépôt, avec pnpm test comme barre.",verb:"effortless_worktree_reintegrate",family:"stacks",args:'{"worktree_path":"../wt-api","bar":{"test":"pnpm test"}}'}),a[3]||(a[3]=n('<h2 id="ce-que-fait-l-agent" tabindex="-1">Ce que fait l&#39;agent <a class="header-anchor" href="#ce-que-fait-l-agent" aria-label="Permalink to &quot;Ce que fait l&#39;agent&quot;">​</a></h2><h3 id="choisir-un-modele-de-stack" tabindex="-1">Choisir un modèle de stack <a class="header-anchor" href="#choisir-un-modele-de-stack" aria-label="Permalink to &quot;Choisir un modèle de stack&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/stacks.html#stack-model-list"><code>effortless_stack_model_list</code></a> liste les modèles : ceux qui sont livrés avec Effortless (<code>rust</code>, <code>node</code>, <code>python</code>, <code>generic</code>, <code>tauri</code>, <code>react</code>, <code>tauri-react</code>, <code>tauri-react-tailwind</code>) et ceux du store du projet. Il fonctionne avant tout projet ; le parcours « Démarrer » s&#39;en sert aussi.</li><li><a href="/Effortless/reference/mcp/stacks.html#stack-model-show"><code>effortless_stack_model_show</code></a> avec <code>model_id</code> détaille un modèle : ses variables, sa stratégie de build et ses commandes de cycle (test, lint, run).</li></ol><h3 id="declarer-un-module-et-ses-langages" tabindex="-1">Déclarer un module et ses langages <a class="header-anchor" href="#declarer-un-module-et-ses-langages" aria-label="Permalink to &quot;Déclarer un module et ses langages&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/stacks.html#stack-add"><code>effortless_stack_add</code></a> avec <code>id</code>. Il déclare la stack (chemin par défaut <code>codebase/&lt;id&gt;/</code>), échafaude le dossier et applique le modèle donné par <code>scaffold_template</code>, avec les variables de <code>vars</code>. Un <code>path</code> hors du projet en fait un module externe : <code>git: true</code> si ce module a son propre dépôt, à suivre comme celui du projet (dérive, hook) ; sans <code>git: true</code>, ce sont des sources partagées, laissées en marge — voir <a href="/Effortless/guide/setup.html">Choisir son organisation</a>.</li><li>Les langages sont pré-remplis par le modèle ; <code>languages</code> passé à l&#39;appel les remplace. Les normes des langages déclarés sont posées dans <code>.ai/ndd/</code> ; celles qui manquent sont nommées dans la réponse.</li><li><a href="/Effortless/reference/mcp/stacks.html#stack-declare-languages"><code>effortless_stack_declare_languages</code></a> corrige ensuite les langages : la nouvelle déclaration remplace la précédente, elle ne fusionne pas. Une liste vide dit « aucune norme ».</li><li><a href="/Effortless/reference/mcp/stacks.html#stack-list"><code>effortless_stack_list</code></a> relit les stacks déclarées.</li></ol><h3 id="echafauder" tabindex="-1">Échafauder <a class="header-anchor" href="#echafauder" aria-label="Permalink to &quot;Échafauder&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/stacks.html#scaffold-list"><code>effortless_scaffold_list</code></a> liste les templates disponibles dans le store du projet.</li><li><a href="/Effortless/reference/mcp/stacks.html#scaffold-apply"><code>effortless_scaffold_apply</code></a> avec <code>template_id</code> et <code>target_dir</code> écrit les fichiers du template dans un dossier. Les fichiers déjà présents sont laissés intacts et rapportés comme ignorés. <a href="/Effortless/reference/mcp/stacks.html#scaffold-apply-project"><code>effortless_scaffold_apply_project</code></a> fait la même chose à la racine du projet.</li><li>Pour apporter votre propre template : <a href="/Effortless/reference/mcp/stacks.html#scaffold-format"><code>effortless_scaffold_format</code></a> rend le schéma d&#39;un manifeste de scaffold, puis <a href="/Effortless/reference/mcp/stacks.html#scaffold-import"><code>effortless_scaffold_import</code></a> avec <code>path</code> l&#39;importe dans le store du projet après validation.</li></ol><h3 id="construire-et-lancer-le-cycle" tabindex="-1">Construire et lancer le cycle <a class="header-anchor" href="#construire-et-lancer-le-cycle" aria-label="Permalink to &quot;Construire et lancer le cycle&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/stacks.html#stack-build"><code>effortless_stack_build</code></a> avec <code>stack_id</code> exécute la commande de build du modèle, depuis le dossier de la stack, et rend le statut, les artefacts et les logs.</li><li><a href="/Effortless/reference/mcp/stacks.html#stack-cycle"><code>effortless_stack_cycle</code></a> avec <code>stack_id</code> et <code>kind</code> (<code>test</code>, <code>lint</code> ou <code>run</code>) rend la commande résolue. Il ne l&#39;exécute pas : l&#39;agent la lance ensuite.</li></ol><h3 id="faire-le-menage" tabindex="-1">Faire le ménage <a class="header-anchor" href="#faire-le-menage" aria-label="Permalink to &quot;Faire le ménage&quot;">​</a></h3><p><a href="/Effortless/reference/mcp/stacks.html#stack-housekeeping"><code>effortless_stack_housekeeping</code></a> constate ce que la politique d&#39;entretien déclarée dans <code>languages[].housekeeping</code> purgerait : quoi, quelle taille, pour quel langage. Sans <code>apply</code>, il ne supprime rien. L&#39;agent ne passe <code>apply: true</code> qu&#39;après votre accord. <code>stack_id</code> limite le constat à une stack.</p><h3 id="deplacer-le-code-sous-codebase" tabindex="-1">Déplacer le code sous <code>codebase/</code> <a class="header-anchor" href="#deplacer-le-code-sous-codebase" aria-label="Permalink to &quot;Déplacer le code sous `codebase/`&quot;">​</a></h3><p><a href="/Effortless/reference/mcp/installation.html#codebase-relocate"><code>effortless_codebase_relocate</code></a> déplace le code resté à la racine vers <code>codebase/&lt;stack&gt;/</code> (stack <code>default</code> sans <code>stack_id</code>). Il commence par un aperçu (<code>dry_run</code> vaut <code>true</code> par défaut) ; l&#39;agent l&#39;exécute réellement (<code>dry_run: false</code>) après votre accord. En mode <strong>Semi-auto</strong>, il est désactivé et le dit.</p><h3 id="reintegrer-un-worktree" tabindex="-1">Réintégrer un worktree <a class="header-anchor" href="#reintegrer-un-worktree" aria-label="Permalink to &quot;Réintégrer un worktree&quot;">​</a></h3><p><a href="/Effortless/reference/mcp/stacks.html#worktree-reintegrate"><code>effortless_worktree_reintegrate</code></a> avec <code>worktree_path</code> (ou <code>worktree_paths</code> pour un projet à plusieurs dépôts) et <code>bar</code>, la barre de contrôle : un objet qui associe <code>test</code>, <code>lint</code>, <code>typecheck</code> ou <code>build</code> à une commande. Le verbe valide d&#39;abord les fichiers en attente du worktree dans un commit, mesure la barre dans le worktree, et ne fusionne que si tout est vert. Après une fusion réussie, le worktree et sa branche sont retirés, sauf avec <code>keep_worktree: true</code>. Le verbe ne crée jamais de worktree.</p><h2 id="ce-que-vous-obtenez" tabindex="-1">Ce que vous obtenez <a class="header-anchor" href="#ce-que-vous-obtenez" aria-label="Permalink to &quot;Ce que vous obtenez&quot;">​</a></h2><ul><li>Des modules déclarés dans <code>effortless.json</code>, des dossiers sous <code>codebase/&lt;id&gt;/</code>, des normes de langage dans <code>.ai/ndd/</code>.</li><li>L&#39;écran <a href="/Effortless/guide/modules.html">Modules</a> montre chaque stack : langages, modèle, normes, version, livraison. Il se lit seulement ; les stacks se déclarent par l&#39;agent ou à la création du workspace.</li><li>Pour un worktree réintégré : le travail est fusionné dans le dépôt, ou rien n&#39;a changé.</li></ul><h2 id="quand-l-agent-est-refuse" tabindex="-1">Quand l&#39;agent est refusé <a class="header-anchor" href="#quand-l-agent-est-refuse" aria-label="Permalink to &quot;Quand l&#39;agent est refusé&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Ce que dit le refus</th><th>Ce qu&#39;il faut faire</th></tr></thead><tbody><tr><td>Stack inconnue (déclaration des langages, ménage)</td><td><code>stack:unknown</code></td><td>Lister les stacks avec <code>effortless_stack_list</code>.</td></tr><tr><td>Stack inconnue (build, cycle)</td><td><code>stacks:stackNotFound</code></td><td>Même geste : <code>effortless_stack_list</code>.</td></tr><tr><td>Id de stack déjà pris, ou vide</td><td>« stack id already exists » / « stack id required »</td><td>Choisir un autre <code>id</code>.</td></tr><tr><td>Langages mal formés</td><td><code>stack:languagesMalformed</code> (les entrées fautives sont nommées)</td><td>Chaque langage est un objet <code>{ id, version, ndd }</code>.</td></tr><tr><td>Source de norme ni <code>embedded</code> ni <code>git</code></td><td><code>stack:nddSourceRefused</code></td><td>Déclarer la source en <code>embedded</code> ou <code>git</code>.</td></tr><tr><td>Stack sans modèle, pour un build</td><td>« la stack n&#39;a pas de modèle (scaffold_template) »</td><td>Déclarer la stack avec un modèle.</td></tr><tr><td>Cycle demandé inconnu</td><td><code>stacks:cycleInvalid</code></td><td><code>kind</code> vaut <code>test</code>, <code>lint</code> ou <code>run</code>.</td></tr><tr><td>Template introuvable</td><td><code>create:templateNotFound</code></td><td>Lister les templates avec <code>effortless_scaffold_list</code>.</td></tr><tr><td>Manifeste importé invalide</td><td>« invalid manifest » avec la liste des erreurs</td><td>Corriger le manifeste d&#39;après <code>effortless_scaffold_format</code>.</td></tr><tr><td>Modèle importé qui déclare une commande à exécuter</td><td><code>create:anchorUntrusted</code></td><td>Retirer la clé <code>anchor</code> du manifeste, ou prendre un modèle livré (<code>effortless_stack_model_list</code>).</td></tr><tr><td>Dossier à réintégrer qui n&#39;est pas un worktree git</td><td><code>worktree:notAWorktree</code></td><td>Créer d&#39;abord le worktree : le verbe n&#39;en crée jamais.</td></tr><tr><td>Worktree sans branche</td><td><code>worktree:detachedHead</code></td><td>Replacer le worktree sur une branche.</td></tr><tr><td>Aucun worktree donné</td><td><code>worktree:noWorktree</code></td><td>Passer <code>worktree_path</code>, ou <code>worktree_paths</code>.</td></tr><tr><td>La barre rougit</td><td><code>worktree:barRed</code> (les commandes en échec sont nommées)</td><td>Corriger dans le worktree, puis relancer ; rien n&#39;a été réintégré.</td></tr><tr><td>Lien symbolique non suivi dans le worktree</td><td><code>worktree:untrackedSymlink</code></td><td>Ignorer le lien dans <code>.gitignore</code> (motif sans barre oblique finale) ou le retirer.</td></tr><tr><td>Conflit à la fusion</td><td><code>worktree:mergeConflict</code> (fichiers nommés)</td><td>Résoudre le conflit dans le worktree et relancer ; la fusion a été annulée.</td></tr><tr><td>Fusion partielle sur plusieurs dépôts</td><td><code>worktree:partialMerge</code></td><td>Corriger la cause, puis relancer sur le seul worktree en échec.</td></tr></tbody></table>',19))])}const b=d(i,[["render",u]]);export{_ as __pageData,b as default};
